// Isolated Multi Hot cabinet components. No full-page capture, balance, result or provider runtime.
let artworkPromise;
export function loadMultiArtwork(){
 if(typeof Image==='undefined')return Promise.resolve(null);
 if(!artworkPromise)artworkPromise=Promise.all(['1','2','3','4','5','rim'].map(name=>new Promise(resolve=>{const image=new Image();image.onload=()=>resolve([name,image]);image.onerror=()=>resolve([name,null]);image.src=multiControlArt[name];}))).then(entries=>({digits:new Map(entries.filter(([name])=>name!=='rim').map(([name,image])=>[Number(name),image])),rim:entries.find(([name])=>name==='rim')?.[1]}));
 return artworkPromise;
}
export function drawMultiMultiplier(c,art,value,x,y,size=39,active=true){
 const image=art?.digits?.get(Number(value));if(!image)return false;
 const h=size*1.42,w=h*image.width/image.height;c.save();if(!active)c.globalAlpha*=.32;c.drawImage(image,x-w/2,y-h/2,w,h);c.restore();return true;
}
export function drawMultiRim(c,art,x,y,w,h){if(!art?.rim)return false;c.drawImage(art.rim,x,y,w,h);return true;}
function cleanFaceImage(node,kind){const image=new Image();image.onload=()=>{const c=document.createElement('canvas');c.width=image.width;c.height=image.height;const ctx=c.getContext('2d');ctx.drawImage(image,0,0);const data=ctx.getImageData(0,0,c.width,c.height);for(let i=0;i<data.data.length;i+=4){const r=data.data[i],g=data.data[i+1],b=data.data[i+2];const alpha=kind==='emblem'?Math.max(0,Math.min(1,(r-Math.max(g,b)*1.15)/30)):Math.max(0,Math.min(1,(Math.min(r,g)-65)/35))*Math.max(0,Math.min(1,(g-b*1.2)/30));data.data[i+3]=Math.round(data.data[i+3]*alpha);}ctx.putImageData(data,0,0);node.src=c.toDataURL('image/png');};image.src=node.src;}
export function applyMultiControlArt(root=document){
 if(root.body?.dataset.game!=='multi_hot_5_video')return false;
 for(const id of ['auto','gamble','collect']){const button=root.getElementById(id);if(button){button.dataset.multiArt='true';button.style.backgroundImage=`url("${multiControlArt[id]}")`;}}
 const spin=root.getElementById('spin');if(spin&&!spin.querySelector('.multi-spin-face')){
  const face=root.createElement('span');face.className='multi-spin-face';face.setAttribute('aria-hidden','true');
  const emblem=root.createElement('img');emblem.className='multi-spin-emblem';emblem.src=multiControlArt.emblem;emblem.alt='';emblem.draggable=false;cleanFaceImage(emblem,'emblem');
  const amount=root.createElement('strong');amount.className='multi-spin-win';
  const unit=root.createElement('small');unit.className='multi-spin-currency';unit.textContent='ETB';
  const chevron=root.createElement('img');chevron.className='multi-spin-chevron';chevron.src=multiControlArt.chevron;chevron.alt='';chevron.draggable=false;cleanFaceImage(chevron,'chevron');
  const stop=root.createElement('span');stop.className='multi-spin-stop';
  face.append(emblem,amount,unit,chevron,stop);spin.append(face);
 }return true;
}
export function updateMultiSpinFace(button,{state='ready',win='0.00',canCollect=false,pending=false,free=0}={}){
 if(!button?.querySelector('.multi-spin-face'))return null;
 const value=String(win),valid=/^(0|[1-9]\d*)(?:\.\d{1,4})?$/.test(value),mode=state==='animating'?'stop':state==='requesting'?'wait':pending?'confirm':free?'free':canCollect&&valid&&Number(value)>0?'win':'idle';
 button.dataset.multiFace=mode;button.querySelector('.multi-spin-win').textContent=valid?value:'0.00';
 if(mode==='win')button.setAttribute('aria-label','Acknowledge '+value+' ETB already credited to your balance. No new spin.');
 return mode;
}
export function drawMultiPayline(c,{game,result,grid,atlas,now,presentedAt,reducedMotion=false,auto=false}){
 if(!result?.winLines?.length||auto)return false;
 const elapsed=Math.max(0,now-presentedAt),line=result.winLines[Math.floor((reducedMotion?0:elapsed)/1200)%result.winLines.length],v=game.visual,cw=v.w/game.reels,ch=v.h/game.rows;
 const pulse=reducedMotion?1:.8+.2*Math.sin(elapsed/210)**2;c.save();
 // The reference keeps the fruit visible; a soft outline replaces the former opaque boxes.
 c.strokeStyle='#f4da62';c.lineWidth=.85;c.globalAlpha=.46*pulse;c.shadowColor='#edc748';c.shadowBlur=5;c.beginPath();line.rows.forEach((row,col)=>{const x=v.x+(col+.5)*cw,y=v.y+(row+.5)*ch;col?c.lineTo(x,y):c.moveTo(x,y);});c.stroke();
 c.shadowBlur=0;c.globalAlpha=1;for(const [row,col]of line.positions){const sprite=atlas.get(grid[row][col]);if(!sprite)continue;const zoom=reducedMotion?1:1+Math.sin(elapsed/260)**2*.022,size=Math.min(cw*.99,ch*1.12)*zoom;c.save();c.beginPath();c.rect(v.x+col*cw+1,v.y+row*ch+1,cw-2,ch-2);c.clip();c.shadowColor='#c9e36f';c.shadowBlur=4*pulse;c.drawImage(sprite,v.x+(col+.5)*cw-size/2,v.y+(row+.5)*ch-size/2,size,size);c.restore();}
 c.restore();return true;
}
export const multiControlArt={"emblem":"data:image/webp;base64,","chevron":"data:image/webp;base64,","auto":"data:image/webp;base64,","gamble":"data:image/webp;base64,","collect":"data:image/webp;base64,","rim":"data:image/webp;base64,","1":"data:image/webp;base64,","2":"data:image/webp;base64,","3":"data:image/webp;base64,","4":"data:image/webp;base64,","5":"data:image/webp;base64,"};
